### Approach
1. **Input Parsing and Distance Matrix Construction**: Read the input and construct a distance matrix from the given distances.
2. **Collect Unique Distances**: Extract all unique distances from the matrix, which will be used as potential disparities for the two groups.
3. **Generate Edge Pairs**: Generate all pairs of edges (distances) sorted by their sum to check partitions in increasing order of their potential sum of disparities.
4. **2-SAT Model**: For each pair of distances (e1, e2), build a 2-SAT model to check if a valid partition exists where one group's disparity is at most e1 and the other's is at most e2.
5. **Check Validity**: Use Kosaraju's algorithm to solve the 2-SAT problem and check if a valid partition exists where both groups are non-empty.

### Solution Code
```python
import sys
from itertools import combinations

def main():
    sys.setrecursionlimit(1 << 25)
    n = int(sys.stdin.readline())
    d = [[0]*n for _ in range(n)]
    for i in range(n-1):
        row = list(map(int, sys.stdin.readline().split()))
        for j, val in enumerate(row):
            d[i][i+1+j] = val
            d[i+1+j][i] = val

    edges = []
    for i in range(n):
        for j in range(i+1, n):
            edges.append(d[i][j])
    edges = sorted(list(set(edges)))

    pairs = []
    for e1 in edges:
        for e2 in edges:
            pairs.append((e1 + e2, e1, e2))
    pairs.sort()

    # 2-SAT implementation
    class TwoSAT:
        def __init__(self, n_vars):
            self.n = n_vars
            self.graph = [[] for _ in range(2 * n_vars)]
            self.rev_graph = [[] for _ in range(2 * n_vars)]

        def add_implication(self, a, b):
            self.graph[a].append(b)
            self.rev_graph[b].append(a)

        def add_clause(self, a, b):
            self.add_implication(a^1, b)
            self.add_implication(b^1, a)

        def dfs(self, node, visited, order):
            if visited[node]:
                return
            visited[node] = True
            for neighbor in self.graph[node]:
                if not visited[neighbor]:
                    self.dfs(neighbor, visited, order)
            order.append(node)

        def solve(self):
            visited = [False] * (2 * self.n)
            order = []
            for i in range(2 * self.n):
                if not visited[i]:
                    self.dfs(i, visited, order)
            visited = [False] * (2 * self.n)
            component = [0] * (2 * self.n)
            current = 0
            for i in reversed(order):
                if not visited[i]:
                    stack = [i]
                    visited[i] = True
                    component[i] = current
                    while stack:
                        node = stack.pop()
                        for neighbor in self.rev_graph[node]:
                            if not visited[neighbor]:
                                visited[neighbor] = True
                                component[neighbor] = current
                                stack.append(neighbor)
                    current += 1
            assignment = [False] * self.n
            for i in range(self.n):
                if component[2*i] == component[2*i +1]:
                    return None
                assignment[i] = component[2*i] > component[2*i +1]
            return assignment

    for sum_e, e1, e2 in pairs:
        ts = TwoSAT(n)
        for u in range(n):
            for v in range(n):
                if u >= v:
                    continue
                if d[u][v] > e1:
                    a = u
                    b = v
                    ts.add_clause(2*a+1, 2*b+1)
                if d[u][v] > e2:
                    a = u
                    b = v
                    ts.add_clause(2*a, 2*b)
        assignment = ts.solve()
        if assignment is not None:
            a_nodes = [i for i in range(n) if assignment[i]]
            b_nodes = [i for i in range(n) if not assignment[i]]
            if a_nodes and b_nodes:
                print(sum_e)
                return

    # If no partition found (which should not happen as per problem statement)
    print(0)

main()
