import math

def evaluate_simple(s):
    tokens = []
    current = []
    for c in s:
        if c in '+-*':
            if current:
                tokens.append(''.join(current))
                current = []
            tokens.append(c)
        else:
            if c != ' ':
                current.append(c)
    if current:
        tokens.append(''.join(current))
    i = 0
    while i < len(tokens):
        if tokens[i] == '*':
            val = int(tokens[i-1]) * int(tokens[i+1])
            tokens = tokens[:i-1] + [str(val)] + tokens[i+2:]
            i -= 1
        else:
            i += 1
    if not tokens:
        return 0
    res = int(tokens[0])
    for i in range(1, len(tokens), 2):
        op = tokens[i]
        num = int(tokens[i+1])
        if op == '+':
            res += num
        elif op == '-':
            res -= num
    return res

