                    value = 0
            sqrt_val = int(math.isqrt(value))
            replacement = str(sqrt_val)
            start_replace = start
            end_replace = start + 2 + bar_length
            if end_replace > len(new_line2):
                end_replace = len(new_line2)
            for j in range(start_replace, end_replace):
